// Solid 2.0 declarations for `escaping-private-helper`, transcribed from
// solid-js@2.0.0-rc.3 (`types/client/flow.d.ts`, `types/types.d.ts`). Every
// signature an arm binds to is byte-faithful to the published one; the surface
// is trimmed, never loosened. README.md records which parts are faithful and
// which are subsets.
//
// Two 2.0 shapes this fixture's arms actually meet, and both are kept:
//
//   * `For` has **three** overloads, not 1.x's one. Only `keyed?: true` keeps
//     1.x's raw `(item, index: Accessor<number>)` children; `keyed: false`
//     hands the callback an `Accessor<T[number]>` and a plain `number`, and the
//     predicate form hands it accessors for both. `builtin.jsx` binds the first,
//     and keeping the other two is what makes that binding a choice rather than
//     the only option on offer.
//   * `For`/`Show` return `Element` from `solid-js`'s own `types.js`, not
//     `JSX.Element`. 2.0 moved `namespace JSX` out of `solid-js` into
//     `@solidjs/web`, so this stub declares neither: nothing here resolves a
//     JSX namespace, and inventing one would be wider than the package.
export type Accessor<T> = () => T;

// Published: `RenderedElement | ArrayElement | (string & {}) | number |
// boolean | null | undefined`. `RenderedElement` is replaced by `unknown`
// because no arm inspects a rendered node; every other member is exact.
export type Element =
  | unknown
  | ArrayElement
  | (string & {})
  | number
  | boolean
  | null
  | undefined;
export interface ArrayElement extends Array<Element> {}

export declare function For<T extends readonly any[], U extends Element>(props: {
  each: T | undefined | null | false;
  fallback?: Element;
  keyed?: true;
  children: (item: T[number], index: Accessor<number>) => U;
}): Element;
export declare function For<T extends readonly any[], U extends Element>(props: {
  each: T | undefined | null | false;
  fallback?: Element;
  keyed: false;
  children: (item: Accessor<T[number]>, index: number) => U;
}): Element;
export declare function For<T extends readonly any[], U extends Element>(props: {
  each: T | undefined | null | false;
  fallback?: Element;
  keyed: (item: T[number]) => any;
  children: (item: Accessor<T[number]>, index: Accessor<number>) => U;
}): Element;

export declare function Show<T>(props: {
  when: T | undefined | null | false;
  keyed: true;
  fallback?: Element;
  children: Element;
}): Element;
